<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesUserVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesTrustedClientVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesScopeVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesGrantedVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesDecisionAtVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesVersionVO;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\UserConsentedScopesAttributes;
use PHPUnit\Framework\TestCase;

final class UserConsentedScopesAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserConsentedScopesAttributes();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserConsentedScopesUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserConsentedScopesUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserConsentedScopesUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserConsentedScopesUserVO::from($userOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserConsentedScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserConsentedScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserConsentedScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserConsentedScopesTrustedClientVO::from($trustedClientOtherValue))->value());
        $scopeOneValue = 'one';
        $scopeOtherValue = 'other';
        $copy = $value->scope($scopeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getScope());
        $this->assertNotEquals('other', $value->getScope());
        $this->assertEquals('one', $value->getScopeOrCurrent(UserConsentedScopesScopeVO::from($scopeOtherValue))->value());
        $this->assertNotEquals('other', $value->getScopeOrCurrent(UserConsentedScopesScopeVO::from($scopeOtherValue))->value());
        $value->unsetScope();
        $this->assertEquals('other', $value->getScopeOrCurrent(UserConsentedScopesScopeVO::from($scopeOtherValue))->value());
        $this->assertNotEquals('one', $value->getScopeOrCurrent(UserConsentedScopesScopeVO::from($scopeOtherValue))->value());
        $grantedOneValue = true;
        $grantedOtherValue = false;
        $copy = $value->granted($grantedOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isGranted());
        $this->assertNotEquals(false, $value->isGranted());
        $this->assertEquals(true, $value->getGrantedOrCurrent(UserConsentedScopesGrantedVO::from($grantedOtherValue))->value());
        $this->assertNotEquals(false, $value->getGrantedOrCurrent(UserConsentedScopesGrantedVO::from($grantedOtherValue))->value());
        $value->unsetGranted();
        $this->assertEquals(false, $value->getGrantedOrCurrent(UserConsentedScopesGrantedVO::from($grantedOtherValue))->value());
        $this->assertNotEquals(true, $value->getGrantedOrCurrent(UserConsentedScopesGrantedVO::from($grantedOtherValue))->value());
        $decisionAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $decisionAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->decisionAt($decisionAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAtOrCurrent(UserConsentedScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAtOrCurrent(UserConsentedScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $value->unsetDecisionAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getDecisionAtOrCurrent(UserConsentedScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getDecisionAtOrCurrent(UserConsentedScopesDecisionAtVO::from($decisionAtOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserConsentedScopesVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserConsentedScopesVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserConsentedScopesVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserConsentedScopesVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
